/// The line every generated file carries. `emb init flatpak --force` rewrites
/// a file only when it finds this in it, so a file the user wrote, or took
/// over by deleting the line, is never overwritten.
const flatpakInitMarker = 'Generated by `emb init flatpak`';

/// The runtime branch written when none is given and flathub cannot be asked.
///
/// Not the packager's own default of 23.08: flatpak reports that one
/// end-of-life, and a generated repo should not start on an unsupported
/// runtime.
const fallbackFlatpakRuntimeVersion = '25.08';

/// The embedder a generated repo builds when none is named.
const defaultEmbedderUri =
    'https://github.com/toyota-connected/ivi-homescreen.git';

